        await workerStorage.createNotification({
          workerId: task.assignedTo,
          type: "task_assigned",
          title: "New Task Assigned",
          message: `You have been assigned a new task: "${task.title}"`,
          relatedId: task.id,
          relatedType: "task",
        });
